  "Sans maximum": "没有最大值",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "没有选择 =所有时间控制,包括未知.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo是来自PGN的,必须在两个玩家的范围内. 在设置边界时,没有Elo的对局是排除的. 失踪或未识别的PGN时间控制器是\"未知\". 如果选择时间控制器,这些对局将被排除在外,除非选择\"未知\".",
  ": indique un nombre valide pour la borne Elo.": ":输入Elo字段的有效号码.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ":输入从0到4000的整数Elo,或留下结合的空白.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ":最低Elo不能超过最高Elo.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "创建一个数据库并将PGN个对局进口到图书馆.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess 大师棋库不支持按 Elo 或用时规则筛选。要筛选大师对局，请选择已导入的数据库，例如 Mega Database。",
  "Source principale": "主要来源",
  "Mes bases PGN": "我的PGN数据库",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "只有主线的着法才会被计算. 分析变化不会膨胀统计数据.",
  "Référence dans chaque ligne": "每行中的引用",
  "Comparer avec": "与",
  "Mes bases de référence": "我的参考数据库",
  "Aucune référence": "没有引用",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "这些筛选条件独立于主数据库。百分比表示在所选参考库中，该着法在当前局面的出现频率。",
  "Probabilité de rencontre": "遇见的可能性",
  "Afficher la probabilité de la ligne": "显示线概率",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "直接在开局浏览器中选择执棋颜色。只计算对手的应手；默认你会走出自己的着法。此估算依据当前显示的变例和所选数据库的筛选条件。如果 PGN 从指定局面开始，估算以该起始局面为前提。",
  "Mode d’analyse": "分析模式",
  "Rapide (~250 ms par coup)": "快速 (每个象棋移动约250 ms)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "较高的深度使分析更加精致,需要更长时间. 从8到30分钟,每个着法的限制为10秒. 如果没有达到目标,≈标记结果;",
