  "Apprendre une ouverture avec quelques lignes commentées.": "通过几条带注释的变化学习开局。",
  "Retrouver les coups d’une courte partie pédagogique.": "找出一盘简短教学对局中的着法。",
  "Lire une partie commentée et retrouver ta progression.": "阅读带注释的对局并保留进度。",
  "Ouvrir {activity}": "打开{activity}",
  "Tes bases d’exemples sont prêtes. Tes modifications et ta progression sont conservées.": "示例数据库已就绪。你的修改和学习进度会保留。",
  "Stockfish est nécessaire pour noter les coups dans Guess the Move. Le répertoire et la lecture sont disponibles sans moteur.": "Guess the Move 需要 Stockfish 来评分。开局库和阅读无需引擎即可使用。",
