  "Stockfish active l’analyse et Guess the Move. Maia est facultatif pour jouer contre un adversaire au style humain. Aucun téléchargement ne commence avant ton choix.": "Stockfish 支持分析和 Guess the Move。Maia 是可选的拟人风格对手。只有在你选择后才会开始下载。",
  "Exemples ajoutés. Choisis une activité pour commencer.": "示例已添加。选择一项活动开始吧。",
