  "Choisis une période valide de 730 jours au maximum.": "请选择有效时段，最长不超过 730 天。",
  "Sélectionne une activité pour explorer ton temps.": "选择一项活动，查看你的时间分配。",
  "Aucune durée mesurée sur cette période. Les nouvelles activités apparaîtront ici automatiquement.": "此时段内没有测得的时长。新活动将自动显示在这里。",
  "{count} activité(s) ont une durée inconnue. Elles ne sont pas comptées comme zéro.": "{count} 项活动的时长未知，不会将其计为零。",
