  "Voir les données": "查看数据",
  "Durées enregistrées pour les activités sélectionnées": "所选活动的已记录时长",
  "Stockfish sert à l’analyse et au jeu classique; Maia reproduit un jeu humain. Les bases de référence et de puzzles restent facultatives.": "Stockfish 用于分析和常规对弈；Maia 模拟人类棋风。参考数据库和战术题库均为可选资源。",
  "Quand ChessGym est ouvert, les versions compatibles des moteurs et les bases installées compatibles sont vérifiées puis actualisées. Les éditions Lumbra se téléchargent séparément sur leur site. Les téléchargements peuvent être volumineux.": "ChessGym 运行时会检查并更新兼容的引擎和已安装数据库。Lumbra 的各个版本需从其网站单独下载。下载文件可能较大。",
  "Licence : {license}": "许可证：{license}",
  "Conditions de licence": "许可条款",
  "Par Michael Jansen. Usage non commercial avec attribution; une licence distincte est nécessaire pour un usage commercial.": "作者：Michael Jansen。署名后可用于非商业用途；商业使用需要单独的许可。",
  "Télécharge cette édition sur le site Lumbra, accepte sa licence, puis indique le fichier .7z ou .pgn présent sur le PC ou serveur de ChessGym.": "从 Lumbra 网站下载此版本并接受其许可条款，然后指定运行 ChessGym 的电脑或服务器上的 .7z 或 .pgn 文件。",
  "Télécharger sur Lumbra": "从 Lumbra 下载",
  "Chemin du fichier téléchargé sur le serveur": "服务器上已下载文件的路径",
  "Ex. C:\\Téléchargements\\Lumbra.7z": "例如 C:\\Downloads\\Lumbra.7z",
  "Utiliser comme référence de maîtres": "用作大师参考数据库",
  "Importer la base téléchargée": "导入已下载的数据库",
  "Les nouvelles éditions Lumbra se téléchargent sur leur site; les mises à jour automatiques ne les remplacent pas.": "Lumbra 的新版本需从其网站下载，自动更新不会替换这些版本。",
  "Taille de l’archive : environ {size} Mo": "压缩包大小：约 {size} MB",
  "Indique le chemin du fichier Lumbra téléchargé.": "请输入已下载的 Lumbra 文件路径。",
  "Lumbra OTB Elite — maîtres 2400+": "Lumbra OTB Elite — 2400+ 大师",
  "Lumbra Gigabase OTB — complète": "Lumbra Gigabase OTB — 完整版",
  "Parties sur échiquier entre deux joueurs classés au moins 2400 Elo. Télécharge l’archive officielle, puis importe-la ici.": "双方等级分均不低于 2400 Elo 的线下对局。请下载官方压缩包，然后在此导入。",
  "Collection complète des parties sur échiquier. L’import et l’indexation peuvent prendre plusieurs heures et beaucoup d’espace disque.": "完整的线下对局合集。导入和建立索引可能需要数小时及大量磁盘空间。",
  "Gratuit avec attribution pour un usage non commercial. Une licence distincte est nécessaire pour un usage commercial.": "署名后可免费用于非商业用途。商业使用需要单独的许可。",
  "Vérification et copie de l’archive Lumbra": "正在验证并复制 Lumbra 压缩包",
  "Lecture de l’archive Lumbra": "正在读取 Lumbra 压缩包",
  "Décompression du PGN Lumbra": "正在解压 Lumbra PGN",
  "Ajout de la base Lumbra à la bibliothèque": "正在将 Lumbra 数据库添加到资料库",
  "Préparation de la base Lumbra": "正在准备 Lumbra 数据库",
  "Cette base Lumbra est déjà installée": "此 Lumbra 数据库已安装",
  "Base Lumbra disponible": "Lumbra 数据库已就绪",
  "7-Zip n’est pas détecté sur le serveur. Installe-le pour importer une archive .7z, ou fournis un PGN déjà extrait.": "服务器上未检测到 7-Zip。请安装它以导入 .7z 压缩包，或提供已解压的 PGN 文件。",
  "Installe 7-Zip sur le serveur, ou décompresse l’archive et importe directement son fichier PGN.": "请在服务器上安装 7-Zip，或先解压压缩包，再直接导入其中的 PGN 文件。",
  "Bonus dans 1 coup : +{seconds} s": "再走 1 步获得奖励：+{seconds} 秒",
  "Seule la résolution sans erreur compte pour le classement. La reconstruction est une statistique secondaire, sans effet sur la cote. Une erreur, une révélation ou un abandon avant la fin de la solution peut faire baisser la cote.": "只有无误解题才计入等级分。局面重建仅作为辅助统计，不影响等级分。在完成解题前出错、查看答案或放弃，可能会降低等级分。",
  "Classé : seule la résolution sans erreur compte. La reconstruction ne change pas la cote.": "评级模式：只统计无误解题。局面重建不影响等级分。",
  "Solution sans erreur.": "解题无误。",
  "Aucun point gagné : une solution complète sans erreur est requise.": "未获得分数：需要完整且无误地解题。",
