  "Les parties sélectionnées seront supprimées de cette base de référence. Le fichier PGN original est conservé. Cette action ne peut pas être annulée.": "所选对局将从此参考数据库中删除。原始 PGN 文件会保留。此操作无法撤销。",
  "Les parties seront copiées dans la base choisie, puis supprimées de cette base de référence. Le fichier PGN original est conservé.": "对局将复制到所选数据库，然后从此参考数据库中删除。原始 PGN 文件会保留。",
  "Une copie indépendante sera créée avec tous les coups, variantes et commentaires.": "将创建一份独立副本，包含所有着法、变例和评论。",
  "{count} partie supprimée.": "已删除 {count} 局。",
