  "Sélectionne des parties pour les dupliquer, les déplacer ou les supprimer. Pour les annoter ou les réviser, duplique-les dans une base personnelle. L’explorer et la recherche de positions utilisent la ligne principale des parties de référence.": "选择对局以复制、移动或删除。若要添加评论或复习，请先将其复制到个人数据库。开局浏览器和局面搜索使用参考对局的主线。",
