  "Le cache mémoire est partagé entre les deux moteurs Stockfish. Ce réglage ne plafonne pas la RAM totale de ChessGym : Maia, les imports et l’interface utilisent aussi de la mémoire.": "内存缓存由两个 Stockfish 引擎共享。此设置不限制 ChessGym 的总内存用量：Maia、导入和界面也会使用内存。",
  "Le budget CPU est partagé entre les calculs et les imports. Les tâches attendent si le budget est déjà utilisé. Les changements s’appliquent aux prochaines tâches.": "CPU 配额由计算和导入共享。配额已用满时，任务会等待。更改将应用于后续任务。",
