  "La durée doit être un nombre entier de millisecondes positif.": "时长必须为正整数，单位为毫秒。",
  "Choisis le mode rapide ou une profondeur Stockfish entière positive.": "请选择快速模式，或将 Stockfish 深度设为正整数。",
