  "La profondeur doit être un entier positif compatible avec le moteur.": "深度必须是与引擎兼容的正整数。",
  "Le temps par position doit être un entier d’au moins 100 ms, représentable sans perte.": "每个局面的用时必须是不小于 100 毫秒、且能够无精度损失地表示的整数。",
  "Choisis une durée ou une profondeur pour analyser la partie.": "请选择分析对局的时长或深度。",
  "Choisis une profondeur positive. Le calcul continue jusqu’à cette cible, sans limite de temps ajoutée. Une profondeur élevée peut demander longtemps ; tu peux arrêter les évaluations ou changer de position.": "请选择大于零的深度。计算将持续到目标深度，不另设时间限制。深度较大时可能耗时很久；你可以停止评估或切换局面。",
  "Choisis une profondeur entière positive compatible avec le moteur.": "请选择引擎支持的正整数深度。",
